/* 128-bit Binary Euclidean GCD Algorithm */
static inline __int128_t gcd128(__int128_t a, __int128_t b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        __int128_t r = a % b;
        a = b;
        b = r;
    }
    return a;
}

static inline Rational rational_make(__int128_t n, __int128_t d) {
    if (d < 0) { n = -n; d = -d; }
    if (n == 0) return (Rational){0LL, 1LL};
    __int128_t g = gcd128(n, d);
    return (Rational){(int64_t)(n / g), (int64_t)(d / g)};
}

static inline Rational rational_mul(Rational a, Rational b) {
    if (a.num == 0 || b.num == 0) return (Rational){0LL, 1LL};
    __int128_t g1 = gcd128(a.num, b.den);
    __int128_t g2 = gcd128(b.num, a.den);
    __int128_t n = (__int128_t)(a.num / g1) * (b.num / g2);
    __int128_t d = (__int128_t)(a.den / g2) * (b.den / g1);
    return (Rational){(int64_t)n, (int64_t)d};
}

static inline Rational rational_add(Rational a, Rational b) {
    if (a.num == 0) return b;
    if (b.num == 0) return a;
    __int128_t g = gcd128(a.den, b.den);
    __int128_t d = ((__int128_t)a.den / g) * b.den;
    __int128_t n = ((__int128_t)a.num * (b.den / g)) + ((__int128_t)b.num * (a.den / g));
    return rational_make(n, d);
}

static inline Rational rational_div(Rational a, Rational b) {
    return rational_mul(a, (Rational){b.den, b.num});
}

void hiram_evidence_init(Evidence* ev) {
    ev->observed_mask = 0;
    ev->values_mask = 0;
}

void hiram_evidence_set(Evidence* ev, uint16_t var_id, bool val) {
    ev->observed_mask |= (1u << var_id);
    if (val) ev->values_mask |= (1u << var_id);
    else     ev->values_mask &= ~(1u << var_id);
}

void hiram_evidence_clear(Evidence* ev, uint16_t var_id) {
    ev->observed_mask &= ~(1u << var_id);
    ev->values_mask &= ~(1u << var_id);
}

/*
 * Flat iterative evaluation loop (MISRA-C:2012 Rule 17.2 Compliant).
 * Circuit nodes are arranged in strict topological order:
 * for every node i, all child indices are strictly < i.
 * Stack usage is deterministic: exactly sizeof(Rational) * CIRCUIT_NODE_COUNT.
 * Zero heap allocation, zero function call overhead, zero recursion risk.
 */
Rational hiram_eval_evidence(const Evidence* ev) {
    Rational memo[CIRCUIT_NODE_COUNT];

    for (uint16_t i = 0; i < CIRCUIT_NODE_COUNT; i++) {
        const CircuitNode* n = &g_circuit_nodes[i];
        Rational res;

        if (n->type == NODE_LITERAL) {
            uint32_t mask = (1u << n->var_id);
            if ((ev->observed_mask & mask) == 0) {
                res = (Rational){1LL, 1LL};
            } else {
                bool val = (ev->values_mask & mask) != 0;
                bool sat = (val && !n->is_negated) || (!val && n->is_negated);
                res = sat ? (Rational){1LL, 1LL} : (Rational){0LL, 1LL};
            }
        } else if (n->type == NODE_PROD) {
            res = (Rational){1LL, 1LL};
            for (uint16_t c = 0; c < n->child_count; c++) {
                uint16_t child_id = g_circuit_children[n->child_offset + c];
                /* child_id < i strictly guaranteed by topological sort */
                res = rational_mul(res, memo[child_id]);
                if (res.num == 0) break;
            }
        } else if (n->type == NODE_SUM) {
            res = (Rational){0LL, 1LL};
            for (uint16_t c = 0; c < n->child_count; c++) {
                uint16_t child_id = g_circuit_children[n->child_offset + c];
                /* child_id < i strictly guaranteed by topological sort */
                Rational w = g_circuit_weights[n->weight_offset + c];
                Rational branch = rational_mul(w, memo[child_id]);
                res = rational_add(res, branch);
            }
        } else {
            res = (Rational){0LL, 1LL};
        }

        memo[i] = res;
    }

    return memo[CIRCUIT_ROOT_ID];
}

HiramAuditReport hiram_audit_hazard(const Evidence* base_ev, Rational max_acceptable_risk) {
    HiramAuditReport rep;
    rep.hazard_threshold = max_acceptable_risk;

    Rational p_e = hiram_eval_evidence(base_ev);
    if (p_e.num == 0) {
        rep.decision = HIRAM_REJECTED_CONTRADICTION;
        rep.hazard_probability = (Rational){0LL, 1LL};
        return rep;
    }

    Evidence ev_hazard = *base_ev;
    hiram_evidence_set(&ev_hazard, HAZARD_VAR_ID, true);
    Rational p_hazard_and_e = hiram_eval_evidence(&ev_hazard);
    Rational posterior = rational_div(p_hazard_and_e, p_e);
    rep.hazard_probability = posterior;

    /* Integer cross-multiplication: posterior > max_acceptable_risk */
    __int128_t lhs = (__int128_t)posterior.num * max_acceptable_risk.den;
    __int128_t rhs = (__int128_t)max_acceptable_risk.num * posterior.den;

    if (lhs > rhs) {
        rep.decision = HIRAM_VETOED_SAFETY_VIOLATION;
    } else {
        rep.decision = HIRAM_APPROVED;
    }
    return rep;
}

